import json
import re

import requests
from bs4 import BeautifulSoup

URL = "http://70.34.217.56:8080/shop?v=2"


def parse_price(text):
    """Extract an integer SEK price from text like 'SEK 6,495', '6 495 kr' or '1 299,99 kr'."""
    if not text:
        return None
    cleaned = re.sub(r"(?i)sek|kr", " ", text)
    cleaned = re.sub(r"[\s\u00a0\u202f\u2009]+", "", cleaned)
    cleaned = re.sub(r"[^\d.,]", "", cleaned)
    if not cleaned or not re.search(r"\d", cleaned):
        return None
    if "." in cleaned and "," in cleaned:
        # Mixed separators: the last one is the decimal separator.
        i = max(cleaned.rfind("."), cleaned.rfind(","))
        cleaned = cleaned[:i].replace(".", "").replace(",", "")
    elif re.fullmatch(r"\d{1,3}(?:[.,]\d{3})+", cleaned):
        # Thousands separators only (e.g. 6,495 or 11.995).
        cleaned = cleaned.replace(".", "").replace(",", "")
    else:
        m = re.match(r"\d+", cleaned)
        if not m:
            return None
        cleaned = m.group(0)
    try:
        return int(cleaned)
    except ValueError:
        return None


def first_text(node, selectors):
    for sel in selectors:
        el = node.select_one(sel)
        if el is not None:
            text = el.get_text(strip=True)
            if text:
                return text
    return None


def price_text(node, selectors):
    for sel in selectors:
        el = node.select_one(sel)
        if el is not None:
            return el.get_text()
    return None


def extract_from_tiles(soup):
    """Primary structure: catalogue tiles (article.sku-tile / [data-sku])."""
    products = []
    for tile in soup.select("article.sku-tile, .sku-tile, [data-sku]"):
        name = first_text(tile, [".tile-title", "h2", "h3", ".title", ".name"])
        text = price_text(tile, [".amount", ".price", "[class*='price']", "[class*='amount']"])
        if not name or not text:
            continue
        price = parse_price(text)
        if price is None:
            continue
        products.append({"name": name, "price_sek": price})
    return products


def extract_from_tables(soup):
    """Fallback structure: table rows with name/price cells."""
    products = []
    for row in soup.select("tr"):
        name = first_text(row, ["td.name", ".name", "td:first-child"])
        text = price_text(row, ["td.price", ".price", "[class*='price']"])
        if not name or not text:
            continue
        price = parse_price(text)
        if price is None:
            continue
        products.append({"name": name, "price_sek": price})
    return products


def extract_generic(soup):
    """Last resort: pair price-like elements with the nearest heading/name."""
    products = []
    for pel in soup.select(".amount, .price, [class*='price'], [class*='amount'], [class*='cost']"):
        price = parse_price(pel.get_text())
        if price is None:
            continue
        container = pel
        for _ in range(6):
            parent = container.parent
            if parent is None or parent.name in ("body", "html", "[document]"):
                break
            container = parent
            name = first_text(
                container,
                ["h1", "h2", "h3", "h4", ".name", ".title", "[class*='name']", "[class*='title']"],
            )
            if name:
                products.append({"name": name, "price_sek": price})
                break
    return products


def main():
    try:
        response = requests.get(URL, timeout=20)
        response.raise_for_status()
    except requests.RequestException:
        print(json.dumps([]))
        return

    if not response.encoding:
        response.encoding = response.apparent_encoding or "utf-8"

    soup = BeautifulSoup(response.text, "html.parser")

    products = extract_from_tiles(soup) or extract_from_tables(soup) or extract_generic(soup)

    seen = set()
    unique = []
